import{_ as e,o as t,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"应用视角的看门狗、健康与 klog","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/watchdog-health.md","filePath":"zh/l1/watchdog-health.md"}'),c={name:"zh/l1/watchdog-health.md"};function l(d,a,h,n,i,p){return t(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="应用视角的看门狗、健康与-klog" tabindex="-1">应用视角的看门狗、健康与 klog <a class="header-anchor" href="#应用视角的看门狗、健康与-klog" aria-label="Permalink to &quot;应用视角的看门狗、健康与 klog&quot;">​</a></h1><h2 id="看门狗-服务-watchdog-l1svc-cat-11" tabindex="-1">看门狗（服务 <code>watchdog</code>，L1SVC cat 11） <a class="header-anchor" href="#看门狗-服务-watchdog-l1svc-cat-11" aria-label="Permalink to &quot;看门狗（服务 `watchdog`，L1SVC cat 11）&quot;">​</a></h2><p>一个注册的槽是一个<em>策略</em>看门狗：持有它的任务必须喂它；超时会 击杀该任务（原因写入日志）而内核继续活着。硬件看门狗（Intel TCO、ACPI WDAT）叠在其下并复位整机 - E2E 套件用真实复位和 第二次启动证明两者。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>watchdog_register(name, timeout_ms, policy)  -&gt; slot</span></span>\n<span class="line"><span>watchdog_start / feed / stop / set_timeout</span></span></code></pre></div><p><code>ush&gt; watchdog</code>（或 sysdiag 经典表）报告槽位与策略；饿死测试 （<code>wd-starve</code>，3000 ms）是 E2E 证明击杀路径的方式。</p><h2 id="健康-服务-health-l1svc-cat-9" tabindex="-1">健康（服务 <code>health</code>，L1SVC cat 9） <a class="header-anchor" href="#健康-服务-health-l1svc-cat-9" aria-label="Permalink to &quot;健康（服务 `health`，L1SVC cat 9）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>health_get_cpu / mem / tasks / io      (the snapshot sources)</span></span>\n<span class="line"><span>health_export(path)                    (valid JSON)</span></span></code></pre></div><p>阈值触发告警进内核日志（<code>CPU-LOCKED</code> 表示一个被钉死的核心、 ...）。应用表面：<code>health</code>（快照 - sysdiag 向导的第一个菜单项）、 <code>health watch</code>（实时监视，ENTER 退出）、<code>health export [path]</code>。</p><h2 id="klog-服务-klog-l1svc-cat-10" tabindex="-1">klog（服务 <code>klog</code>，L1SVC cat 10） <a class="header-anchor" href="#klog-服务-klog-l1svc-cat-10" aria-label="Permalink to &quot;klog（服务 `klog`，L1SVC cat 10）&quot;">​</a></h2><p><code>dmesg [N]</code>（环形日志，最新在末尾）、<code>logcat</code>（结构化：-l level -m module -k key -t seconds -n N -f follow）、<code>logctl status|level|...</code>（运行时控制）。sysdiag 的日志工具子菜单代理 全部三者。</p><h2 id="大应用视图" tabindex="-1">大应用视图 <a class="header-anchor" href="#大应用视图" aria-label="Permalink to &quot;大应用视图&quot;">​</a></h2><p><code>sysdiag</code> 汇集整个可观测性故事：健康快照、内核日志、内存画像、 调度器统计、崩溃记录、日志工具、自检实验室。看门狗 + 健康 + klog 仍可单独触达（经典/直通），供脚本和 E2E 套件使用。</p>',12)])])}const u=e(c,[["render",l]]);export{g as __pageData,u as default};
